-------\n-- MP +5% (cap 150)\n-- Dexterity 4\n-- Mind 5\n-- Accuracy 3\n-- Ranged Accuracy % 6 (cap 20)\n-- HP recovered while healing 9\n-- MP recovered while healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 5)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 150)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, 5)\n    effect:addMod(xi.mod.ACC, 3)\n    effect:addMod(xi.mod.FOOD_RACCP, 6)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 20)\n    effect:addMod(xi.mod.HPHEAL, 9)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/seafood_pitaru.lua"]={["Path"]="scripts/items/seafood_pitaru.lua",["SHA256"]="545833fb51efdf49e41804673501622560a2f5fe25ab50365d47c170af9cdf99",["Text"]="-----------------------------------\n-- ID: 5891\n-- Item: seafood_pitaru\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- MP +8% (cap 120)\n-- Increases rate of magic skill gains by 60%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 8)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 120)\n    effect:addMod(xi.mod.MAGIC_SKILLUP_RATE, 60)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/seafood_stewpot.lua"]={["Path"]="scripts/items/seafood_stewpot.lua",["SHA256"]="356a1b0868b9f1ca54c1a5250133a6a7a5cb1c32e31fbc8988838dae3d540a4b",["Text"]="-----------------------------------\n-- ID: 5238\n-- Item: Seafood Stewpot\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +10% Cap 50\n-- MP +10\n-- Accuracy 5\n-- Ranged Accuracy 5\n-- Evasion 5\n-- hHP 5\n-- hMP 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 50)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.ACC, 5)\n    effect:addMod(xi.mod.RACC, 5)\n    effect:addMod(xi.mod.EVA, 5)\n    effect:addMod(xi.mod.HPHEAL, 5)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/seiryus_sword.lua"]={["Path"]="scripts/items/seiryus_sword.lua",["SHA256"]="7ec0db0a31c2f57395653b22a15605340774d5997168c77ebe7b57562cba1c2a",["Text"]="-----------------------------------\n-- ID: 17659\n-- Item: Seiryu's Sword\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 2, -- TODO: this has negative scaling, as in if you have low dINT it procs more. This is capped dINT.\n        basePower      = math.randomInt(22, 30),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/seki_shuriken_pouch.lua"]={["Path"]="scripts/items/seki_shuriken_pouch.lua",["SHA256"]="4ee8ef3e804668cfeed280e3245c430ecabbbdef4ee595e88d4417f5b0f30fd3",["Text"]="-----------------------------------\n-- ID: 6415\n-- Seki Shuriken Pouch\n-- When used, you will obtain one stack of Seki Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SEKI_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/selbina_earring.lua"]={["Path"]="scripts/items/selbina_earring.lua",["SHA256"]="270df583da1896b9721dc96d6e41ff7ec62f259723649dc76560e76729009c4f",["Text"]="-----------------------------------\n-- ID: 16043\n-- Selbina Earring\n-- Enchantment: \"Teleport\" (Selbina)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.SELBINA_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/senroh_skewer.lua"]={["Path"]="scripts/items/senroh_skewer.lua",["SHA256"]="82e34e5ef69c5eea3f83df3570ce8b20affcc5c5e3307666b5f22f72fa30f210",["Text"]="-----------------------------------\n-- ID: 5982\n-- Item: Senroh Skewer\n-- Food Effect: 30 Mins, All Races\n-----------------------------------\n-- Dexterity 2\n-- Vitality 3\n-- Mind -1\n-- Defense % 25 Cap 150\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 150)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serene_serinette.lua"]={["Path"]="scripts/items/serene_serinette.lua",["SHA256"]="498a2f759a1dcaeb889bc5fdf038e083a70cacd3526c044f5125f7ab34b2ca1c",["Text"]="-----------------------------------\n-- ID: 5424\n-- Item: Serene Serinette\n-- Item Effect: Change Music\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local alliance = target:getAlliance()\n    for i, member in pairs(alliance) do\n        if member:getZoneID() == target:getZoneID() then\n            member:changeMusic(xi.musicSlot.ZONE_DAY, 153)   -- Prelude\n            member:changeMusic(xi.musicSlot.ZONE_NIGHT, 153) -- Prelude\n        end\n    end\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_bass_meuniere.lua"]={["Path"]="scripts/items/serving_of_bass_meuniere.lua",["SHA256"]="cec264deb455715ffa5c97e2a3f3402a57f9f37fe95538f88d8daed3f904e544",["Text"]="-----------------------------------\n-- ID: 4582\n-- Item: serving_of_bass_meuniere\n-- Food Effect: 180Min, All R