Mod(xi.mod.FOOD_HP_CAP, 130)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.AGI, 3)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.FOOD_RACCP, 6)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_batagreen_saute.lua"]={["Path"]="scripts/items/serving_of_batagreen_saute.lua",["SHA256"]="6c0522195c4a723fc7bf6a7159b4b21445bec06673f925a4a8bdb1bfa50aa7af",["Text"]="-----------------------------------\n-- ID: 4553\n-- Item: serving_of_batagreen_sautee\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -2\n-- Ranged ACC % 7\n-- Ranged ACC Cap 15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -2)\n    effect:addMod(xi.mod.FOOD_RACCP, 7)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_bavarois.lua"]={["Path"]="scripts/items/serving_of_bavarois.lua",["SHA256"]="dd359b60e8e089a088fa630b52857d704cceba728ba9e6599e50386c33754ede",["Text"]="-----------------------------------\n-- ID: 5729\n-- Item: serving_of_bavarois\n-- Food Effect: 3Hrs, All Races\n-----------------------------------\n-- HP 20\n-- Intelligence 3\n-- hHP +3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.HPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_bavarois_+1.lua"]={["Path"]="scripts/items/serving_of_bavarois_+1.lua",["SHA256"]="2df42a54fc67a100c1ce8a6ae381ab3a21decc3eb448ff79fc43b896a5c37cd9",["Text"]="-----------------------------------\n-- ID: 5730\n-- Item: Serving of Bavarois +1\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- HP 25\n-- Intelligence 4\n-- hHP +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 25)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.HPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_beaugreen_saute.lua"]={["Path"]="scripts/items/serving_of_beaugreen_saute.lua",["SHA256"]="a1dfcaa2c3d8587994e4f3b2de54d11a7295dbed1ff540c236df3409dba004a0",["Text"]="-----------------------------------\n-- ID: 4572\n-- Item: serving_of_beaugreen_sautee\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -1\n-- Ranged Acc % 7\n-- Ranged Acc Cap 15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.FOOD_RACCP, 7)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_bison_steak.lua"]={["Path"]="scripts/items/serving_of_bison_steak.lua",["SHA256"]="72618086e5e27e8e3717bffded069d91e6f6a065a6360f06026a58fef5e4a02a",["Text"]="-----------------------------------\n-- ID: 5142\n-- Item: serving_of_bison_steak\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Strength 6\n-- Agility 1\n-- Intelligence -3\n-- Attack % 18\n-- Attack Cap 90\n-- Ranged ATT % 18\n-- Ranged ATT Cap 90\n-- Lizard Killer 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.INT, -3)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 90)\n    effect:addMod(xi.mod.FOOD_RATTP, 18)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 90)\n    effect:addMod(xi.mod.LIZARD_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_black_curry.lua"]={["Path"]="scripts/items/serving_of_black_curry.lua",["SHA256"]="b9df530d08001c8d0eeeadc05b538fd81d1ef6a34d21fddb8ed728efccc1c05f",["Text"]="-----------------------------------\n-- ID: 4297\n-- Item: serving_of_black_curry\n-- Food Effect: 180Min, All Races\n-- https://wiki.ffo.jp/html/5680.html\n-----------------------------------\n-- Dexterity 2\n-- Vitality 4\n-- Intelligence 1\n-- Health Regen While Healing 2\n-- Magic Regen While Healing 1\n-- defense % 15 (cap 180)\n-- Accuracy 5\n-- Evasion 5\n-- Ranged ACC 5\n-- Sleep Resist 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nlocal dataTable =\n{\n    [ 1] = { xi.mod.DEX,            4,   2 },\n    [ 2] = { xi.mod.VIT,            6,   4 },\n    [ 3] = { xi.mod.INT,            3,   1 },\n    [ 4] = { xi.mod.HPHEAL,         6,   2 },\n    [ 5] = { xi.mod.MPHEAL,         3,   1 },\n    [ 6] = { xi.mod.FOOD_DEFP,     25,  15 },\n    [ 7] = { xi.mod.FOOD_DEF_CAP, 200, 180 },\n    [ 8] = { xi.mod.ACC,            5,   5 },\n    [ 9] = { xi.mod.RACC,           5,   5 },\n    [10] = { xi.mod.EVA,            5,   5 },\n    [11] = { xi.mod.SLEEPRES,       3,   3 }\n}\n\nitemObject.onEffectGain = function(target, effect)\n    for i = 1, #dataTable do\n        -- Get party factor.\n        local partySize = target:getPartySize()\n        local column = 3\n        if partySize >= 4 then\n            column = 2\n        end\n\n        effect:addMod(dataTable[i][1], dataTable[i][column])\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_black_pudding.lua"]={["Path"]="scripts/items/serving_of_black_pudding.lua",["SHA256"]="0e69042beb876555db307e135b6b246867e3b64f908d7f81814dc7b338b2b495",["Text"]="-----------------------------------\n-- ID: 5552\n-- Item: Serving of Black Pudding\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +8\n-- MP +5% Cap 25\n-- Intelligence +4\n-- HP Recovered while healing +1\n-- MP Recovered while healing +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 5)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 25)\n    effect:addMod(xi.mod.FOOD_HP, 8)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/serving_of_cherry_bavarois.lua"]={["Path"]="scripts/items/serving_of_cherry_bavarois.lua",["SHA256"]="a86ecb92c66572284dc0d57401909f2fe09975286a853b2c4499393dc702ce2a",["Text"]="-----------------------------------\n-- ID: 5745\n-- Item: serving_of_cherry_bavarois\n-- Food Effect: 3Hrs, All Races\n-----------------------------------\n-- HP 25\n-- Intelligence 3\n-- MP 10\n-- HP Recovered While Healing 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodTyp